           const ArResolvedPath& resolvedPath) const = 0;

       virtual std::shared_ptr<ArWritableAsset> _OpenAssetForReplace(
           const ArResolvedPath& resolvedPath) const
       { return nullptr; }

       virtual std::shared_ptr<ArWritableAsset> _OpenAssetForUpdate(
           const ArResolvedPath& resolvedPath) const
       { return nullptr; }

